import numpy as np
def test(Tb,Ab,label):
    cols=[];nm=[]
    for tn,tv in Tb.items():
        for an,av in Ab.items():
            cols.append(tv*av); nm.append(tn+'|'+an)
    X=np.column_stack(cols)
    c,_,_,_=np.linalg.lstsq(X,dA_dt,rcond=None)
    e=np.mean((X@c-dA_dt)**2)/np.var(dA_dt)
    print(label, round(e,8), 'rank',np.linalg.matrix_rank(X), X.shape[1])
    return nm,c
