import numpy as np
try:
    from scipy.optimize import least_squares
    have=True
except Exception as ex:
    have=False; print('no scipy',ex)
if have:
    def model(p,t,A):
        Ts = p[0]/t + p[1] + p[2]*t**2
        return -Ts*(1+p[3]*A)**(-p[4]) + p[5]*A*t + p[6]*A**2
    def model2(p,t,A):
        Ts = p[0]/t + p[1] + p[2]*t**2
        return -Ts*np.exp(-p[3]*A**p[4]) + p[5]*A*t + p[6]*A**2
    best={}
    rng=np.random.default_rng(0)
    for name,mf in [('pow',model),('expA',model2)]:
        bb=None
        for s in range(60):
            p0=rng.uniform(-1,3,7)
            try:
                r=least_squares(lambda p: mf(p,t,A)-dA_dt, p0, max_nfev=3000)
                if bb is None or r.cost<bb.cost: bb=r
            except Exception: pass
        e=np.mean((mf(bb.x,t,A)-dA_dt)**2)/np.var(dA_dt)
        print(name,e,np.round(bb.x,4))
        best[name]=bb
    res=dA_dt-model(best['pow'].x,t,A)
    print('resid corr with t,A,1/t,t^2,A*t:',[round(np.corrcoef(res,v)[0,1],3) for v in [t,A,1/t,t**2,A*t,A**2]])
